(()=>{const search=document.getElementById('master-search'),buttons=[...document.querySelectorAll('[data-filter]')],cards=[...document.querySelectorAll('.master')];let category='all';const groups={iran:[1,2,4,6,7,8],world:[0,1,2,3,5,8,9,12],art:[10,11]};function apply(){const query=search.value.trim();for(const [index,card] of cards.entries()){const text=card.textContent;card.hidden=!(text.includes(query)&&(category==='all'||groups[category].includes(index)))}}for(const button of buttons)button.addEventListener('click',()=>{category=button.dataset.filter;buttons.forEach(b=>b.classList.toggle('selected',b===button));apply()});search.addEventListener('input',apply)})();
